            {actionError && <div className="bg-red-50 p-2.5 rounded-lg text-red-600 text-[8px] font-black uppercase text-center border border-red-100 flex items-center justify-center gap-2 animate-bounce"><ShieldAlert size={12}/> {actionError}</div>}

            {showReturnInput && (
                <div className="flex items-center gap-2 bg-red-50 p-2 rounded-xl border border-red-100 animate-in slide-in-from-bottom-2 shadow-sm">
                    <input autoFocus value={returnReason} onChange={e => setReturnReason(e.target.value)} placeholder="JUSTIFICACIÓN TÉCNICA..." className="flex-1 bg-white border border-red-200 px-3 py-2.5 rounded-lg text-[9px] font-black text-red-900 uppercase outline-none shadow-inner" />
                    <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-4 py-2.5 rounded-lg text-[9px] font-black uppercase shadow-md active:scale-95">ENVIAR</button>
                    <button onClick={() => setShowReturnInput(false)} className="p-1 text-red-400 hover:text-red-600"><X size={20}/></button>
                </div>
            )}

            <div className="flex items-center gap-3">
                {activeRole === UserRole.SUPERADMIN && <button onClick={() => { if(confirm('¿BORRAR EXPEDIENTE?')) { deleteRequest(data.id); handleClose(); }}} className="h-11 w-11 flex items-center justify-center text-slate-400 hover:text-red-600 bg-white border border-slate-200 rounded-xl transition-all shadow-sm active:scale-95"><Trash2 size={18}/></button>}
                <div className="flex-1 flex gap-2">
                    {showReturnButton && !showReturnInput && <button onClick={() => setShowReturnInput(true)} className="flex-1 px-4 h-11 bg-white border border-red-200 text-[9px] font-black text-red-600 rounded-xl uppercase flex items-center justify-center gap-2 hover:bg-red-50 transition-all active:scale-95 shadow-sm"><RotateCcw size={14}/> RETORNAR</button>}
                    {canDeriveUI && <button onClick={() => handleTransition(Status.DERIVACION)} className="flex-1 h-11 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 px-3 transition-all active:scale-95"><UserCheck size={14}/> DERIVAR</button>}
                    {canExecuteUI && <button onClick={() => handleTransition(Status.EJECUCION)} className="flex-1 h-11 bg-amber-500 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-amber-600 px-3 transition-all active:scale-95"><PlayCircle size={14}/> EJECUTAR</button>}
                    {canFinalizeUI && <button onClick={() => handleTransition(Status.FINALIZADO)} className="flex-1 h-11 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg flex items-center justify-center gap-2 hover:bg-emerald-700 px-3 transition-all active:scale-95"><ShieldCheck size={14}/> FINALIZAR</button>}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, Area } from '../types';
import { LayoutDashboard, Plus, Briefcase, LogOut, Shield, ArrowLeftRight } from 'lucide-react';
import { NewRequestModal } from './NewRequestModal';
import { RequestDetailModal } from './RequestDetailModal';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { currentUser, logout, viewMode, setViewMode, activeRole, switchHybridRole, setSelectedRequestId } = useSisreq();
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Los hooks deben estar arriba. Si no hay usuario, retornamos null después.
  if (!currentUser) return null;

  const getInitials = (name: string) => name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);

  const isHybridUser = currentUser.role === UserRole.ADMIN && !!currentUser.area;

  const handleToggleProfile = () => {
    setSelectedRequestId(null);
    switchHybridRole();
  };

  const getRoleBadge = () => {
    if (isHybridUser) {
        return (
            <button 
                onClick={handleToggleProfile}
                className={`flex items-center gap-1.5 px-2 py-0.5 rounded-lg text-[9px] font-bold border transition-all ${
                    activeRole === UserRole.ADMIN 
                    ? 'bg-red-50 text-red-600 border-red-100 hover:bg-red-100' 
                    : 'bg-indigo-50 text-indigo-600 border-indigo-100 hover:bg-indigo-100'
                }`}
            >
                <ArrowLeftRight size={10} />
                {activeRole === UserRole.ADMIN ? 'MODO ADMIN' : `JEFE ${currentUser.area?.toUpperCase()}`}
            </button>
        );
    }

    switch (currentUser.role) {
        case UserRole.SUPERADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-900 text-white font-bold border border-slate-950 tracking-wider">SUPERADMIN</span>;
        case UserRole.ADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-red-50 text-red-600 font-bold border border-red-100 tracking-wider uppercase">ADMIN CENTRAL</span>;
        case UserRole.HEAD: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-indigo-50 text-indigo-600 font-bold border border-indigo-100 tracking-wider uppercase">JEFE {currentUser.area}</span>;
        default: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-100 text-slate-500 font-bold border border-slate-200 tracking-wider uppercase">ANALYST</span>;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200/60 z-30 shrink-0 h-16 px-6 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 pr-8 border-r border-slate-200/50">
                <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-100">
                    <LayoutDashboard size={20} strokeWidth={2.5} />
                </div>
                <h1 className="text-lg font-black tracking-tighter text-slate-900 leading-none">SISREQ</h1>
            </div>

            <nav className="flex items-center gap-6">
                {currentUser.role === UserRole.SUPERADMIN ? (
                    <div className="flex bg-slate-100 p-1 rounded-xl gap-1 border border-slate-200/50">
                        <button 
                            onClick={() => setViewMode('work')} 
                            className={`px-5 py-1.5 rounded-lg transition-all text-xs font-black uppercase tracking-widest ${viewMode === 'work' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                        >
                            Operativo
                        </button>
                        <button 
                            onClick={() => setViewMode('superadmin')} 
                            className={`px-5 py-1.5 rounded-lg transition-all text-xs font-black uppercase tracking-widest ${viewMode === 'superadmin' ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                        >
                            Master
                        </button>
                    </div>
                ) : (
                    <div className="flex items-center gap-2.5 px-4 py-1.5 bg-slate-50 rounded-full border border-slate-100">
                        {activeRole === UserRole.ADMIN ? <Shield size={14} className="text-red-500"/> : <Briefcase size={14} className="text-indigo-500"/>}
                        <span className="text-[11px] font-black uppercase tracking-[0.1em] text-slate-600">
                            {activeRole === UserRole.ADMIN ? 'Consola de Control Central' : `${activeRole} • ${currentUser.area || 'General'}`}
                        </span>
                    </div>
                )}
            </nav>
        </div>

        <div className="flex items-center gap-5">
            {(activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN || activeRole === UserRole.HEAD) && (
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2 rounded-xl flex items-center gap-2.5 text-xs font-black uppercase tracking-widest transition-all shadow-xl shadow-indigo-100 active:scale-95 group"
                >
                    <Plus size={16} strokeWidth={3} className="group-hover:rotate-90 transition-transform" /> 
                    Nuevo Requerimiento
                </button>
            )}

            <div className="h-8 w-px bg-slate-200 mx-1"></div>

            <div className="flex items-center gap-4">
                <div className="flex flex-col items-end">
                    <span className="text-sm font-black text-slate-800 leading-none mb-1.5">{currentUser.name}</span>
                    {getRoleBadge()}
                </div>
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-slate-100 to-slate-200 border border-white shadow-sm flex items-center justify-center font-black text-xs text-slate-600 shrink-0 ring-4 ring-slate-50">
                    {getInitials(currentUser.name)}
                </div>
                <button 
                    onClick={logout} 
                    className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" 
                    title="Cerrar Sesión"
                >
                    <LogOut size={20} />
                </button>
            </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0 relative z-10">
        {children}
        <div className="absolute inset-0 opacity-[0.15] pointer-events-none z-[-1]" 
             style={{backgroundImage: 'radial-gradient(#94a3b8 1px, transparent 1px)', backgroundSize: '30px 30px'}}>
        </div>
      </main>

      <NewRequestModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      <RequestDetailModal />
    </div>
  );
};
